def ErlangC(A, N):
    if (N-A<=0): 
        return 1 
    L = (A**N / factorial(N)) * (N / (N - A))
    sum_ = 0
    for i in range(N):
        sum_ += (A**i) / factorial(i)
    return (L / (sum_ + L))
def calc_sl(row):
    if row['duration'] == 0:
        return 0
    A = row['duration']
    T = 20 
    aht = row['duration'] * 3600 / row['calls']
    for staff in range(1000):
        P = ErlangC(A, staff)
        sl = (1 - (P * math.exp(-((staff - A) * (T / aht))))) * 100
        if sl >= 80: 
            return staff

