def unlist(m):
  q = []
  for x in m:
    if (type(x) is list):
      for y in x:
        q.append(y)
      continue
    q.append(x)
  for i in range(len(q)):
    if (type(q[i]) is not list):
      if (i == (len(q)-1)):
        return q
      continue
    else:
      break
  for elem in q:
    if (type(elem) is list):
      z = unlist(elem)
      q.remove(elem)
      for item in z:
        q.append(item)
  return q

