    print(f"loading pkl: {os.path.abspath(path)}")
    assert os.path.isfile(path)
    try:
        with open(path, "rb") as f:
            content = pickle.load(f)
    except UnicodeDecodeError:  
        with open(path, "rb") as f:
            content = pickle.load(f, encoding='latin1')
    return content

