def isEvenWord(word):
    if word == '':  
        return True
    else:
        last_letter = word[-1]
        if word.count(last_letter)  % 2 != 0:
            return False
        else:
            next_word = word[0:-1] 
            next_word = word.replace(last_letter, '') 
            return isEvenWord(next_word)

